import hashlib
import os
import tempfile

def sha256_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        while True:
            b = f.read(4096)
            if not b:
                break
            h.update(b)
    return h.hexdigest()

m = int(input().strip())
events = [input().strip().split(maxsplit=2) for _ in range(m)]

with tempfile.TemporaryDirectory() as tmp:
    baseline = {"app.conf": "port=8080", "auth.conf": "mfa=true", "routes.json": "[]"}
    manifest = {}
    for name, body in baseline.items():
        p = os.path.join(tmp, name)
        with open(p, "w", encoding="utf-8") as f:
            f.write(body)
        manifest[name] = sha256_file(p)

    for ev in events:
        op = ev[0]
        fname = os.path.basename(ev[1])
        p = os.path.join(tmp, fname)
        if op in ("MODIFY", "ADD") and len(ev) == 3:
            with open(p, "w", encoding="utf-8") as f:
                f.write(ev[2])
        elif op == "DELETE" and os.path.exists(p):
            os.remove(p)

    present = set(os.listdir(tmp))
    for name in sorted(set(manifest) | present):
        p = os.path.join(tmp, name)
        if name not in manifest:
            print(f"{name}: UNTRACKED")
        elif not os.path.exists(p):
            print(f"{name}: MISSING")
        elif sha256_file(p) != manifest[name]:
            print(f"{name}: TAMPERED")
        else:
            print(f"{name}: OK")

import os
import tempfile
from urllib.parse import unquote

raw = input().rstrip("\n")
decoded = unquote(raw).replace("\\", "/")

with tempfile.TemporaryDirectory() as base:
    base_real = os.path.realpath(base)
    if not decoded or "\x00" in decoded or decoded.startswith("/") or (len(decoded) >= 2 and decoded[1] == ":"):
        print("BLOCKED_TRAVERSAL")
    else:
        target_real = os.path.realpath(os.path.join(base_real, decoded))
        try:
            inside = os.path.commonpath([base_real, target_real]) == base_real
        except ValueError:
            inside = False
        if not inside or target_real == base_real:
            print("BLOCKED_TRAVERSAL")
        else:
            rel = os.path.relpath(target_real, base_real).replace("\\", "/")
            print(f"SAFE: {rel}")

ROLE_PERMS = {
    "viewer": {"read"},
    "editor": {"read", "write"},
    "admin": {"read", "write", "delete"},
}
VALID_ACTIONS = {"read", "write", "delete"}

q = int(input().strip())
for _ in range(q):
    actor, role, action, owner, scope = input().strip().split()
    if role not in ROLE_PERMS or action not in VALID_ACTIONS or scope not in ("public", "private"):
        print("DENY (INVALID_POLICY)")
    elif action not in ROLE_PERMS[role]:
        print("DENY (ROLE_FORBIDDEN)")
    elif scope == "private" and role != "admin" and actor != owner:
        print("DENY (OWNERSHIP_REQUIRED)")
    else:
        print("ALLOW")

fname, size_s, magic = input().strip().split()
size = int(size_s)
magic = magic.lower()
ALLOWED = {"png": "89504e47", "jpg": "ffd8ff", "pdf": "25504446"}
DANGEROUS = {"exe", "sh", "php", "js", "bat", "py"}

parts = fname.lower().split(".")
final_ext = parts[-1] if len(parts) >= 2 else ""

if size <= 0 or size > 5_000_000:
    print("REJECT: SIZE_LIMIT")
elif len(parts) < 2 or final_ext not in ALLOWED or any(seg in DANGEROUS for seg in parts[1:]):
    print("REJECT: BAD_EXTENSION")
elif not magic.startswith(ALLOWED[final_ext]):
    print("REJECT: MAGIC_MISMATCH")
else:
    print("ACCEPT")

n, thresh = map(int, input().split())
fails = acc = 0
ip_fails = {}
ip_users = {}

for _ in range(n):
    parts = input().strip().split()
    if len(parts) < 3:
        continue
    status = parts[0]
    kv = dict(p.split("=", 1) for p in parts[1:] if "=" in p)
    ip = kv.get("ip", "unknown")
    user = kv.get("user", "unknown")
    if status == "ACCEPTED":
        acc += 1
    elif status == "FAILED":
        fails += 1
        ip_fails[ip] = ip_fails.get(ip, 0) + 1
        ip_users.setdefault(ip, set()).add(user)

print(f"Failed:{fails} Accepted:{acc}")
alerts = [(ip, cnt) for ip, cnt in ip_fails.items() if cnt >= thresh]
if not alerts:
    print("Alerts: NONE")
else:
    alerts.sort(key=lambda x: (-x[1], x[0]))
    for ip, cnt in alerts:
        print(f"ALERT {ip}: {cnt} failures ({len(ip_users[ip])} users)")

from collections import deque

n, w, k = map(int, input().split())
windows = {}
breached = {}

for _ in range(n):
    ts_s, ip = input().strip().split()
    ts = int(ts_s)
    dq = windows.setdefault(ip, deque())
    dq.append(ts)
    while dq and dq[0] < ts - w:
        dq.popleft()
    if ip not in breached and len(dq) >= k:
        breached[ip] = ts

if not breached:
    print("NO_BREACH")
else:
    for ip in sorted(breached):
        print(f"BREACH {ip} at t={breached[ip]}")

import shlex

SEV = {
    "TAMPER_DETECTED": "CRITICAL",
    "ROOT_LOGIN_FAIL": "CRITICAL",
    "PRIV_ESC_DENIED": "HIGH",
    "TRAVERSAL_BLOCKED": "HIGH",
    "RATE_LIMIT_HIT": "MEDIUM",
}

n = int(input().strip())
counts = {"CRITICAL": 0, "HIGH": 0, "MEDIUM": 0, "INFO": 0}
high_alerts = []

for _ in range(n):
    line = input().strip()
    if not line:
        continue
    try:
        tokens = shlex.split(line)
    except ValueError:
        continue
    kv = {}
    for tok in tokens:
        if "=" in tok:
            k, v = tok.split("=", 1)
            kv[k] = v
    if "ts" not in kv or "event" not in kv:
        continue
    sev = SEV.get(kv["event"], "INFO")
    counts[sev] += 1
    if sev in ("CRITICAL", "HIGH"):
        actor = kv.get("actor", "unknown")
        msg = kv.get("msg", "")
        high_alerts.append(f"[{sev}] {kv['ts']} {kv['event']} actor={actor} msg={msg}")

print(f"CRITICAL:{counts['CRITICAL']} HIGH:{counts['HIGH']} MEDIUM:{counts['MEDIUM']} INFO:{counts['INFO']}")
for a in high_alerts:
    print(a)

import ipaddress

m, k = map(int, input().split())
nets = []
for _ in range(m):
    raw_net = input().strip()
    try:
        nets.append(ipaddress.ip_network(raw_net, strict=False))
    except ValueError:
        pass

blocked = allowed = malformed = 0
hits = []
for _ in range(k):
    parts = input().strip().split()
    if len(parts) < 2:
        malformed += 1
        continue
    ip_s, ep = parts[0], parts[1]
    try:
        ip_obj = ipaddress.ip_address(ip_s)
    except ValueError:
        malformed += 1
        continue
    matched = None
    for net in nets:
        if ip_obj.version == net.version and ip_obj in net:
            matched = str(net)
            break
    if matched:
        blocked += 1
        hits.append(f"[BLOCK] {ip_s} -> {ep} (matched {matched})")
    else:
        allowed += 1

print(f"Blocked:{blocked} Allowed:{allowed} Malformed:{malformed}")
for h in hits:
    print(h)

RANK = {"CRITICAL": 0, "HIGH": 1, "MEDIUM": 2}
SECRET_KEYS = ("SECRET", "PASSWORD", "PASS", "TOKEN", "API_KEY")

n = int(input().strip())
findings = []

for _ in range(n):
    line = input().strip()
    if not line or line.startswith("#") or "=" not in line:
        continue
    k, v = line.split("=", 1)
    k_up = k.strip().upper()
    v_clean = v.strip()
    v_low = v_clean.lower()

    if k_up == "DEBUG" and v_low == "true":
        findings.append((0 if False else RANK["HIGH"], "HIGH: DEBUG_ENABLED"))
    elif k_up == "TLS_MIN" and v_clean in ("1.0", "1.1"):
        findings.append((RANK["HIGH"], "HIGH: WEAK_TLS"))
    elif k_up in ("COOKIE_SECURE", "COOKIE_HTTPONLY") and v_low == "false":
        findings.append((RANK["MEDIUM"], "MEDIUM: INSECURE_COOKIE"))
    elif k_up == "CORS_ORIGIN" and v_clean == "*":
        findings.append((RANK["MEDIUM"], "MEDIUM: WILDCARD_CORS"))

    if any(sk in k_up for sk in SECRET_KEYS):
        if v_clean and not (v_clean.startswith("${") and v_clean.endswith("}")):
            findings.append((RANK["CRITICAL"], f"CRITICAL: HARDCODED_SECRET ({k_up}=***REDACTED***)"))

if not findings:
    print("HARDENED")
else:
    findings.sort()
    print(f"Findings:{len(findings)}")
    for _, msg in findings:
        print(msg)

import hashlib
import os
import tempfile

def sha256_bytes(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        while True:
            b = f.read(4096)
            if not b:
                break
            h.update(b)
    return h.hexdigest()

req_path = input().strip()
override = input().strip()
fail_cnt = int(input().strip())

with tempfile.TemporaryDirectory() as ws:
    ws_real = os.path.realpath(ws)
    cfg_dir = os.path.join(ws_real, "config")
    os.makedirs(cfg_dir, exist_ok=True)
    cfg_path = os.path.join(cfg_dir, "server.cfg")
    with open(cfg_path, "w", encoding="utf-8") as f:
        f.write("TLS_MIN=1.2\nDEBUG=false\n")
    baseline_hash = sha256_bytes(cfg_path)

    if override != "OK":
        with open(cfg_path, "w", encoding="utf-8") as f:
            f.write(override + "\n")

    norm_req = req_path.replace("\\", "/")
    if not norm_req or norm_req.startswith("/") or "\x00" in norm_req:
        print("Posture: FAIL | Reason: PATH_TRAVERSAL")
    else:
        target = os.path.realpath(os.path.join(ws_real, norm_req))
        try:
            inside = os.path.commonpath([ws_real, target]) == ws_real
        except ValueError:
            inside = False
        if not inside or target == ws_real:
            print("Posture: FAIL | Reason: PATH_TRAVERSAL")
        elif not os.path.isfile(target):
            print("Posture: FAIL | Reason: FILE_NOT_FOUND")
        else:
            issues = []
            if sha256_bytes(target) != baseline_hash:
                issues.append("INTEGRITY_DRIFT")
            with open(target, "r", encoding="utf-8") as rf:
                for line in rf:
                    if "=" in line:
                        k, v = (x.strip() for x in line.split("=", 1))
                        if k == "DEBUG" and v.lower() == "true":
                            issues.append("CONFIG_DEBUG_ON")
                        if k == "TLS_MIN" and v in ("1.0", "1.1"):
                            issues.append("CONFIG_WEAK_TLS")
            if fail_cnt >= 5:
                issues.append("LOG_BRUTE_FORCE")
            if not issues:
                print("Posture: PASS | Issues: NONE")
            else:
                print("Posture: ACTION_REQUIRED | Issues: " + ", ".join(sorted(issues)))
